const form = $('Pedido Excel').first().json;
// Busca un campo del formulario sin importar mayúsculas, espacios ni guiones
const campo = (...nombres) => {
  const norm = s => String(s).toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g, '').replace(/[\s_-]|de/g, '');
  const k = Object.keys(form).find(x => nombres.map(norm).includes(norm(x)));
  return k ? form[k] : '';
};
const lineas = $input.all()
  .map(i => Object.values(i.json).filter(v => v !== null && v !== '').join(' '))
  .filter(l => l.trim() !== '');
return [{ json: {
  cliente: campo('cliente'),
  canal: 'excel',
  texto: lineas.join('\n'),
  fecha_indicada: campo('fecha_entrega', 'fecha de entrega', 'fecha')
}}];

