const raw = String($json.output ?? '');
const txt = raw.replace(/```json|```/g, '').replace(/[\r\n]+/g, '').trim();
const ini = txt.indexOf('{'), fin = txt.lastIndexOf('}');
let r = null, error = '';
try { r = raw ? JSON.parse(txt.slice(ini, fin + 1)) : null; } catch (e) { error = 'La IA no devolvió un JSON válido'; }
const ok = r && ['ACEPTADO', 'ACLARAR', 'DERIVAR'].includes(r.decision) && Array.isArray(r.items);
if (!ok) {
  return { json: {
    decision: 'REVISAR',
    motivo: error || (raw ? 'Respuesta con estructura incorrecta' : 'La IA devolvió una respuesta vacía'),
    respuesta_cruda: raw.slice(0, 1000), items: [],
    mensaje_cliente: 'Recibimos tu mensaje, en breve te responde alguien del equipo.'
  }};
}
return { json: { ...r, parse_ok: true } };

const r = $('Parsear respuesta').first().json;
const p = $('Preparar pedido').first().json;
const cat = $input.all().map(i => i.json);
const porCodigo = new Map(cat.filter(c => String(c.codigo || '').trim()).map(c => [String(c.codigo).trim(), c]));
const porNombre = new Map(cat.map(c => [String(c.producto).trim().toLowerCase(), c]));
const errores = [], correcciones = [];

if (r.decision === 'REVISAR') return [{ json: { ...p, ...r, errores_validacion: [r.motivo] } }];

// Regla fija de tamaño por defecto: Café = 10 cm (si no, el más chico); La Pana = 22 cm (si no, el más grande)
const cm = x => { const m = String(x.producto).match(/(\d+)\s*cm/i); return m ? Number(m[1]) : null; };
function tamanoDefecto(c) {
  if (!['Café', 'La Pana'].includes(p.cliente)) return null;
  const enteras = cat.filter(x => x.familia === c.familia && cm(x) !== null);
  if (enteras.length < 2) return null;
  if (p.cliente === 'Café') return enteras.find(x => cm(x) === 10) || [...enteras].sort((a, b) => cm(a) - cm(b))[0];
  return enteras.find(x => cm(x) === 22) || [...enteras].sort((a, b) => cm(b) - cm(a))[0];
}

const items = (r.items || []).map(it => {
  const cod = String(it.codigo || '').trim();
  let c = (cod && porCodigo.get(cod)) || porNombre.get(String(it.producto || '').trim().toLowerCase());
  if (!c) { errores.push(`"${it.texto_original}": no identificado en el catálogo`); return { ...it, valido: false }; }
  if (/por defecto/i.test(it.observacion || '')) {
    const d = tamanoDefecto(c);
    if (d && d.producto !== c.producto) { correcciones.push(`${c.producto} → ${d.producto}`); c = d; }
  }
  const cant = Number(it.cantidad);
  if (!(cant > 0)) errores.push(`"${it.texto_original}": cantidad inválida`);
  return { ...it, codigo: String(c.codigo || ''), producto: c.producto, seccion: c.seccion, unidad: c.unidad, cantidad: cant, valido: true };
});

const minDias = p.cliente === 'Particular' ? 1 : 2;
const fecha = r.fecha_entrega || p.fecha_entrega_default;
const dias = DateTime.fromISO(fecha).diff(DateTime.fromISO(p.fecha_recepcion), 'days').days;
if (r.decision === 'ACEPTADO') {
  if (!items.length) errores.push('Pedido aceptado sin productos');
  if (isNaN(dias)) errores.push('Fecha de entrega inválida');
  else if (dias < minDias) errores.push(`No cumple la anticipación mínima de ${minDias} día(s)`);
}

const decision = (r.decision === 'ACEPTADO' && errores.length) ? 'REVISAR' : r.decision;
return [{ json: {
  ...p, decision,
  motivo: decision === 'REVISAR' ? errores.join('; ') : (r.motivo || ''),
  fecha_entrega: fecha, items,
  pregunta_cliente: r.pregunta_cliente || '',
  mensaje_cliente: decision === 'REVISAR'
    ? 'Recibimos tu mensaje, en breve te responde alguien del equipo.'
    : decision === 'ACEPTADO'
      ? `¡Gracias! Registramos tu pedido para el ${DateTime.fromISO(fecha).setLocale('es').toFormat('cccc dd/MM')}: ${items.map(i => `${i.cantidad} ${i.producto}`).join(', ')}.`
      : r.mensaje_cliente,
  errores_validacion: errores,
  correcciones_validador: correcciones
}}];

const p = $input.first().json;
return p.items.map(it => ({ json: {
  id_pedido: p.id_pedido, fecha_recepcion: p.fecha_recepcion, fecha_entrega: p.fecha_entrega,
  cliente: p.cliente, canal: p.canal, codigo: it.codigo, producto: it.producto,
  seccion: it.seccion, cantidad: it.cantidad, unidad: it.unidad,
  observacion: it.observacion || '', estado: 'aceptado'
}}));
